insert into public.training_lesson_packs(course_id,revision,content) values('67402026-1002-4000-8000-000001000001','2026-10-02.v1','{"key": "power", "domain": "electrical", "title": ["Power & component identification", "הספק וזיהוי רכיבים"], "goal": ["Trace power on an unpowered robot and identify what each device does.", "עקבו אחר ההספק ברובוט מנותק וזהו את תפקידו של כל רכיב."], "sources": [["WPILib · illustrated robot wiring", "https://docs.wpilib.org/en/stable/docs/zero-to-robot/step-1/intro-to-frc-robot-wiring.html"], ["WPILib · battery basics", "https://docs.wpilib.org/en/stable/docs/hardware/hardware-basics/robot-battery.html"]], "steps": [["Disconnect the battery. Identify battery connector, main breaker, distribution device, controller and motor before touching wiring.", "נתקו סוללה. זהו מחבר סוללה, מפסק ראשי, רכיב חלוקה, בקר ומנוע לפני מגע בחיווט."], ["Follow the installed power path using device labels and the manufacturer diagram. Record unknown devices rather than guessing.", "עקבו אחר מסלול ההספק לפי סימוני הרכיבים ותרשים היצרן. תעדו רכיבים לא מזוהים בלי לנחש."], ["Separate motor power, control/data and sensor connections in your sketch. Record the actual breaker and wire specifications for one branch.", "הפרידו בשרטוט בין הספק למנוע, בקרה/נתונים וחיבורי חיישנים. תעדו מפרט מפסק וחוט בפועל בענף אחד."], ["Compare the sketch against the physical robot with a reviewer. Powered checks require a supervised test plan and clear moving parts.", "השוו את השרטוט לרובוט עם בודק. בדיקות עם מתח דורשות תוכנית מפוקחת והרחקה מחלקים נעים."]], "mistakes": [["A controller status LED does not prove the battery can supply load.", "נורית בקר אינה מוכיחה שהסוללה מסוגלת לספק זרם בעומס."], ["Do not infer an installed wire gauge or breaker rating from a CAD model.", "אין להסיק עובי חוט או דירוג מפסק מותקן ממודל CAD."]], "practical": [["Map one power branch", "מיפוי ענף הספק אחד"], ["Inspect the battery installation", "בדיקת התקנת הסוללה"]], "rubrics": [[["Battery disconnected before inspection", "סוללה נותקה לפני הבדיקה"], ["Every device in the chosen branch identified on a labeled sketch", "כל רכיב בענף מזוהה בשרטוט מסומן"], ["Actual wire and protection ratings recorded with their source", "מפרטי החוט וההגנה בפועל תועדו עם מקור"], ["Reviewer compares sketch to the installed robot", "בודק משווה את השרטוט לרובוט המותקן"]], [["Battery identity and visible condition recorded", "זהות הסוללה ומצבה החזותי תועדו"], ["Connector seating, retention and cable protection inspected unpowered", "נבדקו חיבור, קיבוע והגנת כבלים ללא מתח"], ["Mounting and access to disconnect demonstrated", "הודגמו קיבוע וגישה לניתוק"], ["Defects recorded; responsible reviewer decides readiness", "תועדו ליקויים; בודק אחראי מחליט על מוכנות"]]], "quizId": "67402026-1002-4000-8000-000001000002", "practicalIds": ["67402026-1002-4000-8000-000001000003", "67402026-1002-4000-8000-000001000004"], "sourceChecked": "2026-10-02", "sourcePolicy": "Linked living documentation; confirm the installed hardware and current instructions before practical work."}'::jsonb) on conflict(course_id) do nothing;
insert into public.training_assessments(id,course_id,title,instructions,assessment_type,questions,required,graded,max_score,passing_score,max_attempts,target_type,sort_order) values('67402026-1002-4000-8000-000001000002','67402026-1002-4000-8000-000001000001','Knowledge check
---HE---
בדיקת ידע','Answer all ten questions. Review the lesson after feedback; practical qualification also requires both demonstrations to be approved.
---HE---
ענו על עשר השאלות. חזרו לשיעור לאחר משוב; הסמכה מעשית דורשת גם אישור לשתי ההדגמות.','quiz','[{"id": "q1", "prompt": "Before changing power wiring?\n---HE---\nלפני שינוי חיווט הספק?", "kind": "single_choice", "options": ["Only disable software\n---HE---\nרק להשבית תוכנה", "Only stop the wheels\n---HE---\nרק לעצור גלגלים", "Disconnect the battery\n---HE---\nלנתק סוללה"], "points": 1}, {"id": "q2", "prompt": "What does CAN carry?\n---HE---\nמה CAN מעביר?", "kind": "single_choice", "options": ["Compressed air\n---HE---\nאוויר דחוס", "Control data\n---HE---\nנתוני בקרה", "Motor supply current\n---HE---\nזרם הספק למנוע"], "points": 1}, {"id": "q3", "prompt": "An unknown connector should be…\n---HE---\nמחבר לא מזוהה צריך…", "kind": "single_choice", "options": ["Identified from its device documentation\n---HE---\nלהיות מזוהה לפי תיעוד הרכיב", "Connected by matching shape alone\n---HE---\nלהתחבר לפי צורה בלבד", "Tested by swapping power wires\n---HE---\nלהיבדק בהחלפת חוטי מתח"], "points": 1}, {"id": "q4", "prompt": "Where do you verify branch protection?\n---HE---\nאיפה מאמתים הגנת ענף?", "kind": "single_choice", "options": ["A photograph of another robot\n---HE---\nתצלום רובוט אחר", "Wire color only\n---HE---\nצבע החוט בלבד", "Actual hardware labels and applicable documentation\n---HE---\nסימוני החומרה והתיעוד המתאים"], "points": 1}, {"id": "q5", "prompt": "A good no-load voltage proves…\n---HE---\nמתח תקין ללא עומס מוכיח…", "kind": "single_choice", "options": ["All power connectors are sound\n---HE---\nשכל מחברי ההספק תקינים", "Only the voltage under that measured condition\n---HE---\nרק את המתח בתנאי המדידה", "Full battery capacity\n---HE---\nקיבולת סוללה מלאה"], "points": 1}, {"id": "q6", "prompt": "A loose battery needs…\n---HE---\nסוללה רופפת דורשת…", "kind": "single_choice", "options": ["Secure mounting before operation\n---HE---\nקיבוע לפני הפעלה", "Higher driving speed\n---HE---\nמהירות נסיעה גבוהה יותר", "A software offset\n---HE---\nהיסט בתוכנה"], "points": 1}, {"id": "q7", "prompt": "Which evidence identifies the tested battery?\n---HE---\nאיזו ראיה מזהה את הסוללה שנבדקה?", "kind": "single_choice", "options": ["Robot paint color\n---HE---\nצבע הרובוט", "Team ranking\n---HE---\nדירוג הקבוצה", "Recorded battery ID\n---HE---\nמזהה סוללה מתועד"], "points": 1}, {"id": "q8", "prompt": "A power path sketch should include…\n---HE---\nשרטוט מסלול הספק צריך לכלול…", "kind": "single_choice", "options": ["Only CAN devices\n---HE---\nרק רכיבי CAN", "Source, protection and load\n---HE---\nמקור, הגנה ועומס", "Only the motor\n---HE---\nרק את המנוע"], "points": 1}, {"id": "q9", "prompt": "Damage on a power cable means…\n---HE---\nנזק בכבל הספק מחייב…", "kind": "single_choice", "options": ["Stop and obtain inspection/repair before use\n---HE---\nלעצור ולבצע בדיקה/תיקון לפני שימוש", "Cover it in the photograph\n---HE---\nלהסתיר בתצלום", "Increase the breaker rating\n---HE---\nלהגדיל דירוג מפסק"], "points": 1}, {"id": "q10", "prompt": "Who confirms physical readiness?\n---HE---\nמי מאשר מוכנות פיזית?", "kind": "single_choice", "options": ["A quiz score alone\n---HE---\nציון מבחן בלבד", "The CAD viewer\n---HE---\nמציג ה-CAD", "A responsible reviewer using the inspection evidence\n---HE---\nבודק אחראי על סמך ראיות הבדיקה"], "points": 1}]'::jsonb,true,true,10,8,5,'all',10) on conflict(id) do nothing;
