insert into public.training_lesson_packs(course_id,revision,content) values('67402026-1002-4000-8000-000002000001','2026-10-02.v1','{"key": "can", "domain": "electrical", "title": ["CAN & sensors", "CAN וחיישנים"], "goal": ["Trace a bus, inspect real connectors and reproduce a fault safely.", "עקבו אחר אפיק, בדקו מחברים אמיתיים ושחזרו תקלה בבטחה."], "sources": [["WPILib · CAN wiring", "https://docs.wpilib.org/en/stable/docs/hardware/hardware-basics/can-wiring-basics.html"], ["CTRE · CAN bring-up", "https://v5.docs.ctr-electronics.com/en/latest/ch08_BringUpCAN.html"]], "steps": [["Draw your installed bus, including each device, bus identity and the two endpoints. Label H and L at every connector.", "שרטטו את האפיק המותקן, הרכיבים, זהות האפיק ושני קצותיו. סמנו H ו-L בכל מחבר."], ["Open the CAN wiring workshop in the robot lab for connector-specific illustrations. Inspect full seating, crimps and strain relief with power disconnected.", "פתחו את סדנת CAN במעבדת הרובוטים לאיורי מחברים. בדקו ישיבה מלאה, לחיצות והקלת מאמצים ללא מתח."], ["For the documented two-terminator bus, measure H–L resistance unpowered. Around 60 Ω is consistent with two 120 Ω terminations; it is not proof of error-free communication.", "באפיק המתועד עם שני נגדי סיום, מדדו התנגדות H–L ללא מתח. כ-60 אוהם מתאימים לשני נגדי 120 אוהם; אין בכך הוכחה לתקשורת ללא שגיאות."], ["With supervised power and the robot disabled, record discovered devices and error observations. Repeat the same observation after repair.", "עם מתח בפיקוח ורובוט מושבת, תעדו רכיבים שזוהו ושגיאות. חזרו על אותה בדיקה לאחר התיקון."]], "mistakes": [["A missing device can be wiring, configuration or power; do not replace hardware before isolating the cause.", "רכיב חסר עשוי לנבוע מחיווט, הגדרה או הספק; בידדו סיבה לפני החלפת חומרה."], ["Sensor connectors are not interchangeable just because they fit. Check voltage and pinout.", "מחברי חיישנים אינם חלופיים רק מפני שהם מתאימים מכנית. בדקו מתח ומיפוי פינים."]], "practical": [["Trace and inspect one CAN bus", "מעקב ובדיקת אפיק CAN"], ["Reproduce and retest a connector fault", "שחזור ובדיקה חוזרת של תקלת מחבר"]], "rubrics": [[["Bus identity, devices and endpoints labeled", "זהות אפיק, רכיבים וקצוות סומנו"], ["H/L and termination arrangement verified against documentation", "H/L וסידור נגדי סיום אומתו מול תיעוד"], ["Connector-specific inspection recorded unpowered", "בדיקת המחבר תועדה ללא מתח"], ["Resistance value and meter condition recorded without claiming full validation", "תועדו התנגדות ותנאי מדידה בלי לטעון לאימות מלא"]], [["Use a supervised spare harness; never inject a short on the robot", "משתמשים בצמה רזרבית בפיקוח; אין ליצור קצר ברובוט"], ["Fault symptom and affected devices recorded", "תועדו תסמין ורכיבים מושפעים"], ["One repair/change recorded", "תועד תיקון/שינוי אחד"], ["Repeated equivalent tests linked to the repair task", "בדיקות חוזרות זהות קושרו למשימת התיקון"]]], "quizId": "67402026-1002-4000-8000-000002000002", "practicalIds": ["67402026-1002-4000-8000-000002000003", "67402026-1002-4000-8000-000002000004"], "sourceChecked": "2026-10-02", "sourcePolicy": "Linked living documentation; confirm the installed hardware and current instructions before practical work."}'::jsonb) on conflict(course_id) do nothing;
insert into public.training_assessments(id,course_id,title,instructions,assessment_type,questions,required,graded,max_score,passing_score,max_attempts,target_type,sort_order) values('67402026-1002-4000-8000-000002000002','67402026-1002-4000-8000-000002000001','Knowledge check
---HE---
בדיקת ידע','Answer all ten questions. Review the lesson after feedback; practical qualification also requires both demonstrations to be approved.
---HE---
ענו על עשר השאלות. חזרו לשיעור לאחר משוב; הסמכה מעשית דורשת גם אישור לשתי ההדגמות.','quiz','[{"id": "q1", "prompt": "Yellow CAN wire connects to…\n---HE---\nחוט CAN צהוב מתחבר ל…", "kind": "single_choice", "options": ["Battery positive\n---HE---\nפלוס סוללה", "H\n---HE---\nH", "L\n---HE---\nL"], "points": 1}, {"id": "q2", "prompt": "Resistance is measured…\n---HE---\nהתנגדות נמדדת…", "kind": "single_choice", "options": ["With power disconnected\n---HE---\nללא מתח", "While enabled\n---HE---\nבמצב מופעל", "With the motor spinning\n---HE---\nכשהמנוע מסתובב"], "points": 1}, {"id": "q3", "prompt": "Two 120 Ω endpoints in parallel give about…\n---HE---\nשני נגדי 120 אוהם במקביל נותנים כ…", "kind": "single_choice", "options": ["240 Ω\n---HE---\n240 אוהם", "0 Ω\n---HE---\n0 אוהם", "60 Ω\n---HE---\n60 אוהם"], "points": 1}, {"id": "q4", "prompt": "About 120 Ω may indicate…\n---HE---\nכ-120 אוהם עשויים להעיד על…", "kind": "single_choice", "options": ["A full battery\n---HE---\nסוללה מלאה", "One disconnected or missing termination\n---HE---\nנגד סיום חסר או מנותק", "Guaranteed good communication\n---HE---\nתקשורת תקינה בוודאות"], "points": 1}, {"id": "q5", "prompt": "A correct resistance reading proves…\n---HE---\nהתנגדות תקינה מוכיחה…", "kind": "single_choice", "options": ["Only part of the electrical checks\n---HE---\nרק חלק מהבדיקות החשמליות", "All devices have correct IDs\n---HE---\nשלכל הרכיבים מזהים נכונים", "No intermittent faults exist\n---HE---\nשאין תקלות לסירוגין"], "points": 1}, {"id": "q6", "prompt": "All devices after one connector disappear. Inspect…\n---HE---\nכל הרכיבים אחרי מחבר נעלמים. בדקו…", "kind": "single_choice", "options": ["The robot paint\n---HE---\nאת צבע הרובוט", "Only the first wheel\n---HE---\nרק את הגלגל הראשון", "That connector and downstream wiring\n---HE---\nאת המחבר והחיווט שאחריו"], "points": 1}, {"id": "q7", "prompt": "Strain relief should…\n---HE---\nהקלת מאמצים צריכה…", "kind": "single_choice", "options": ["Replace termination\n---HE---\nלהחליף נגד סיום", "Keep cable load off the terminal\n---HE---\nלמנוע עומס כבל על ההדק", "Pull the conductor tight\n---HE---\nלמתוח את המוליך"], "points": 1}, {"id": "q8", "prompt": "Sensor pinout comes from…\n---HE---\nמיפוי פיני חיישן מגיע מ…", "kind": "single_choice", "options": ["The exact device documentation\n---HE---\nתיעוד הרכיב המדויק", "Its color alone\n---HE---\nצבעו בלבד", "Another sensor that fits\n---HE---\nחיישן אחר שמתאים"], "points": 1}, {"id": "q9", "prompt": "A fair repair retest uses…\n---HE---\nבדיקה חוזרת הוגנת משתמשת ב…", "kind": "single_choice", "options": ["An unrelated mechanism\n---HE---\nמנגנון לא קשור", "Only one successful screenshot\n---HE---\nצילום מוצלח אחד בלבד", "The same fault observation procedure\n---HE---\nאותו נוהל תצפית לתקלה"], "points": 1}, {"id": "q10", "prompt": "Where should extra termination be added?\n---HE---\nאיפה מוסיפים נגד סיום נוסף?", "kind": "single_choice", "options": ["At every cable joint\n---HE---\nבכל חיבור כבל", "Only where the bus documentation requires it\n---HE---\nרק היכן שתיעוד האפיק מחייב", "At every device\n---HE---\nבכל רכיב"], "points": 1}]'::jsonb,true,true,10,8,5,'all',10) on conflict(id) do nothing;
insert into public.training_assessment_answer_keys(assessment_id,answers) values('67402026-1002-4000-8000-000002000002','{"q1": ["H\n---HE---\nH"], "q2": ["With power disconnected\n---HE---\nללא מתח"], "q3": ["60 Ω\n---HE---\n60 אוהם"], "q4": ["One disconnected or missing termination\n---HE---\nנגד סיום חסר או מנותק"], "q5": ["Only part of the electrical checks\n---HE---\nרק חלק מהבדיקות החשמליות"], "q6": ["That connector and downstream wiring\n---HE---\nאת המחבר והחיווט שאחריו"], "q7": ["Keep cable load off the terminal\n---HE---\nלמנוע עומס כבל על ההדק"], "q8": ["The exact device documentation\n---HE---\nתיעוד הרכיב המדויק"], "q9": ["The same fault observation procedure\n---HE---\nאותו נוהל תצפית לתקלה"], "q10": ["Only where the bus documentation requires it\n---HE---\nרק היכן שתיעוד האפיק מחייב"]}'::jsonb) on conflict(assessment_id) do nothing;
insert into public.training_assessments(id,course_id,title,instructions,assessment_type,questions,required,graded,max_attempts,target_type,sort_order) values('67402026-1002-4000-8000-000002000003','67402026-1002-4000-8000-000002000001','Trace and inspect one CAN bus
---HE---
מעקב ובדיקת אפיק CAN','Trace and inspect one CAN bus
• Bus identity, devices and endpoints labeled
