insert into public.training_lesson_packs(course_id,revision,content) values('67402026-1002-4000-8000-000003000001','2026-10-02.v1','{"key": "inspection", "domain": "electrical", "title": ["Wiring & mounting inspection", "בדיקת חיווט וקיבוע"], "goal": ["Find failures before vibration and motion expose them.", "זהו כשלים לפני שרעידות ותנועה חושפות אותם."], "sources": [["WPILib · wiring best practices", "https://docs.wpilib.org/en/stable/docs/hardware/hardware-basics/wiring-best-practices.html"], ["WPILib · illustrated connections", "https://docs.wpilib.org/en/stable/docs/zero-to-robot/step-1/intro-to-frc-robot-wiring.html"]], "steps": [["Create an inspection path from the battery through one mechanism. Use the actual installed hardware and connector instructions.", "צרו מסלול בדיקה מהסוללה דרך מנגנון אחד. השתמשו בחומרה המותקנת ובהוראות המחבר."], ["With power disconnected, inspect seating, conductor capture, exposed strands, abrasion and retention.", "ללא מתח, בדקו ישיבה, אחיזת מוליך, גידים חשופים, שחיקה ונעילה."], ["Move the mechanism only as safely permitted, checking the entire cable travel for tension, pinch points and service access.", "הזיזו מנגנון רק באופן מותר ובטוח, ובדקו לאורך התנועה מתח בכבל, נקודות צביטה וגישה לתחזוקה."], ["Assign each defect an owner in Work. Photograph or sketch the location and repeat the inspection after repair.", "הקצו לכל ליקוי אחראי בעבודה. צלמו או שרטטו מיקום וחזרו על הבדיקה לאחר תיקון."]], "mistakes": [["A cable tie can hold a cable while the terminal still has a poor connection. Inspect both.", "אזיקון יכול להחזיק כבל כשההדק מחובר גרוע. בדקו את שניהם."], ["Inspection is not a powered stress test. Agree a supervised procedure separately.", "בדיקה חזותית אינה בדיקת עומס עם מתח. קבעו נוהל מפוקח בנפרד."]], "practical": [["Inspect a complete mechanism harness", "בדיקת צמת מנגנון מלאה"], ["Close a defect with repair evidence", "סגירת ליקוי עם ראיות תיקון"]], "rubrics": [[["All connectors listed with exact device identity", "כל המחברים רשומים עם זהות רכיב מדויקת"], ["Seating and retention checked unpowered", "ישיבה ונעילה נבדקו ללא מתח"], ["Full safe mechanism travel checked for pinch/strain", "כל טווח התנועה הבטוח נבדק לצביטה/מאמץ"], ["Findings include location and evidence", "הממצאים כוללים מיקום וראיות"]], [["Original defect and owner recorded", "ליקוי מקורי ואחראי תועדו"], ["Repair method matches connector instructions", "שיטת התיקון תואמת להוראות המחבר"], ["Same inspection repeated after repair", "אותה בדיקה חזרה לאחר תיקון"], ["Reviewer signs off or requests a specific correction", "בודק מאשר או מבקש תיקון מוגדר"]]], "quizId": "67402026-1002-4000-8000-000003000002", "practicalIds": ["67402026-1002-4000-8000-000003000003", "67402026-1002-4000-8000-000003000004"], "sourceChecked": "2026-10-02", "sourcePolicy": "Linked living documentation; confirm the installed hardware and current instructions before practical work."}'::jsonb) on conflict(course_id) do nothing;
insert into public.training_assessments(id,course_id,title,instructions,assessment_type,questions,required,graded,max_score,passing_score,max_attempts,target_type,sort_order) values('67402026-1002-4000-8000-000003000002','67402026-1002-4000-8000-000003000001','Knowledge check
---HE---
בדיקת ידע','Answer all ten questions. Review the lesson after feedback; practical qualification also requires both demonstrations to be approved.
---HE---
ענו על עשר השאלות. חזרו לשיעור לאחר משוב; הסמכה מעשית דורשת גם אישור לשתי ההדגמות.','quiz','[{"id": "q1", "prompt": "A terminal should grip…\n---HE---\nהדק צריך לאחוז…", "kind": "single_choice", "options": ["The correctly prepared conductor\n---HE---\nבמוליך שהוכן כראוי", "Only the insulation\n---HE---\nרק בבידוד", "A cable tie\n---HE---\nבאזיקון"], "points": 1}, {"id": "q2", "prompt": "Loose exposed strands can…\n---HE---\nגידים חשופים משוחררים עלולים…", "kind": "single_choice", "options": ["Improve strain relief\n---HE---\nלשפר הקלת מאמצים", "Increase accuracy\n---HE---\nלהגדיל דיוק", "Cause unintended electrical contact\n---HE---\nליצור מגע חשמלי לא רצוי"], "points": 1}, {"id": "q3", "prompt": "Check cable travel…\n---HE---\nבודקים מסלול כבל…", "kind": "single_choice", "options": ["Only in CAD\n---HE---\nרק ב-CAD", "Across the safe mechanism range\n---HE---\nבכל טווח המנגנון הבטוח", "Only at rest\n---HE---\nרק במנוחה"], "points": 1}, {"id": "q4", "prompt": "A defect record needs…\n---HE---\nרישום ליקוי צריך…", "kind": "single_choice", "options": ["Location, symptom and owner\n---HE---\nמיקום, תסמין ואחראי", "Only “broken”\n---HE---\nרק ״שבור״", "Only a team number\n---HE---\nרק מספר קבוצה"], "points": 1}, {"id": "q5", "prompt": "A sharp edge near wiring needs…\n---HE---\nקצה חד ליד חיווט דורש…", "kind": "single_choice", "options": ["Higher voltage\n---HE---\nמתח גבוה יותר", "More software logging only\n---HE---\nרק יותר רישום תוכנה", "Protection or rerouting before operation\n---HE---\nהגנה או שינוי מסלול לפני הפעלה"], "points": 1}, {"id": "q6", "prompt": "A tug check is performed…\n---HE---\nבדיקת משיכה נעשית…", "kind": "single_choice", "options": ["While driving\n---HE---\nתוך נסיעה", "Gently, unpowered, per connector instructions\n---HE---\nבעדינות, ללא מתח ולפי הוראות המחבר", "By pulling the whole robot\n---HE---\nבמשיכת כל הרובוט"], "points": 1}, {"id": "q7", "prompt": "Service access matters because…\n---HE---\nגישה לתחזוקה חשובה כי…", "kind": "single_choice", "options": ["Parts must be inspected and replaced\n---HE---\nצריך לבדוק ולהחליף רכיבים", "It changes the game score\n---HE---\nהיא משנה ניקוד משחק", "It removes the need for labels\n---HE---\nהיא מבטלת צורך בסימון"], "points": 1}, {"id": "q8", "prompt": "After repair…\n---HE---\nלאחר תיקון…", "kind": "single_choice", "options": ["Erase the original defect\n---HE---\nמוחקים את הליקוי המקורי", "Skip reviewer feedback\n---HE---\nמדלגים על משוב", "Repeat the relevant inspection\n---HE---\nחוזרים על הבדיקה המתאימה"], "points": 1}, {"id": "q9", "prompt": "Connector torque should be…\n---HE---\nמומנט מחבר צריך להיות…", "kind": "single_choice", "options": ["The same for all connectors\n---HE---\nזהה לכל המחברים", "Taken from its exact specification\n---HE---\nלפי המפרט המדויק", "As high as possible\n---HE---\nגבוה ככל האפשר"], "points": 1}, {"id": "q10", "prompt": "A mounting check includes…\n---HE---\nבדיקת קיבוע כוללת…", "kind": "single_choice", "options": ["Retention and interference through motion\n---HE---\nאחיזה והפרעות בזמן תנועה", "Only appearance\n---HE---\nרק מראה", "Only wireless signal\n---HE---\nרק אות אלחוטי"], "points": 1}]'::jsonb,true,true,10,8,5,'all',10) on conflict(id) do nothing;
insert into public.training_assessment_answer_keys(assessment_id,answers) values('67402026-1002-4000-8000-000003000002','{"q1": ["The correctly prepared conductor\n---HE---\nבמוליך שהוכן כראוי"], "q2": ["Cause unintended electrical contact\n---HE---\nליצור מגע חשמלי לא רצוי"], "q3": ["Across the safe mechanism range\n---HE---\nבכל טווח המנגנון הבטוח"], "q4": ["Location, symptom and owner\n---HE---\nמיקום, תסמין ואחראי"], "q5": ["Protection or rerouting before operation\n---HE---\nהגנה או שינוי מסלול לפני הפעלה"], "q6": ["Gently, unpowered, per connector instructions\n---HE---\nבעדינות, ללא מתח ולפי הוראות המחבר"], "q7": ["Parts must be inspected and replaced\n---HE---\nצריך לבדוק ולהחליף רכיבים"], "q8": ["Repeat the relevant inspection\n---HE---\nחוזרים על הבדיקה המתאימה"], "q9": ["Taken from its exact specification\n---HE---\nלפי המפרט המדויק"], "q10": ["Retention and interference through motion\n---HE---\nאחיזה והפרעות בזמן תנועה"]}'::jsonb) on conflict(assessment_id) do nothing;
insert into public.training_assessments(id,course_id,title,instructions,assessment_type,questions,required,graded,max_attempts,target_type,sort_order) values('67402026-1002-4000-8000-000003000003','67402026-1002-4000-8000-000003000001','Inspect a complete mechanism harness
