insert into public.training_assessments(id,course_id,title,instructions,assessment_type,questions,required,graded,max_attempts,target_type,sort_order) values('67402026-1002-4000-8000-000003000004','67402026-1002-4000-8000-000003000001','Close a defect with repair evidence
---HE---
סגירת ליקוי עם ראיות תיקון','Close a defect with repair evidence
