insert into public.training_lesson_packs(course_id,revision,content) values('67402026-1002-4000-8000-000004000001','2026-10-02.v1','{"key": "fastening", "domain": "mechanical", "title": ["Mechanical fastening", "חיבורים מכניים"], "goal": ["Build and inspect a documented joint instead of guessing tightness.", "בנו ובדקו חיבור מתועד במקום לנחש הידוק."], "sources": [["REV · FRC Robot Basics, mechanical assembly examples", "https://www.revrobotics.com/content/docs/FRC-Robot-Basics-Guide.pdf"]], "steps": [["Select a documented joint on a reference CAD assembly. Identify its parts, fastener, mating surfaces and access.", "בחרו חיבור מתועד בהרכבת CAD לדוגמה. זהו חלקים, מחבר, משטחי מגע וגישה."], ["For your practice joint, record fastener size, material, engagement and locking method from its drawing/specification. Missing specifications need review.", "בחיבור התרגול תעדו גודל מחבר, חומר, עומק הברגה ושיטת נעילה מהשרטוט/מפרט. מפרט חסר דורש בדיקה."], ["Assemble an unpowered sample with the specified tool. Never substitute an arbitrary torque value.", "הרכיבו דוגמה ללא מתח עם הכלי המוגדר. אין להחליף מפרט בערך מומנט שרירותי."], ["Check alignment, access and interference. Record a repeatable inspection method and have the reviewer inspect the joint.", "בדקו יישור, גישה והפרעות. תעדו שיטת בדיקה חוזרת ובקשו בדיקת החיבור."]], "mistakes": [["CAD geometry does not prove joint strength or preload.", "גאומטריית CAD אינה מוכיחה חוזק או עומס הידוק."], ["A witness mark helps detect movement; it does not prove correct torque.", "סימן ביקורת מסייע לזהות תזוזה; הוא אינו מוכיח מומנט תקין."]], "practical": [["Assemble a documented practice joint", "הרכבת חיבור תרגול מתועד"], ["Inspect and improve service access", "בדיקה ושיפור גישה לתחזוקה"]], "rubrics": [[["Drawing and fastener identity attached", "צורפו שרטוט וזהות המחבר"], ["Tool and specified tightening method recorded", "תועדו כלי ושיטת הידוק מוגדרת"], ["Alignment and seating verified", "אומתו יישור וישיבה"], ["Reviewer checks assembled sample", "בודק בודק דוגמה מורכבת"]], [["Original access problem demonstrated", "הודגמה בעיית הגישה המקורית"], ["Proposed change preserves required clearances", "שינוי מוצע שומר על מרווחים נדרשים"], ["Disassembly/reassembly demonstrated on sample", "הודגמו פירוק והרכבה בדוגמה"], ["Unknown structural effects escalated for engineering review", "השפעות מבניות לא ידועות הועברו לבדיקה הנדסית"]]], "quizId": "67402026-1002-4000-8000-000004000002", "practicalIds": ["67402026-1002-4000-8000-000004000003", "67402026-1002-4000-8000-000004000004"], "sourceChecked": "2026-10-02", "sourcePolicy": "Linked living documentation; confirm the installed hardware and current instructions before practical work."}'::jsonb) on conflict(course_id) do nothing;
insert into public.training_assessments(id,course_id,title,instructions,assessment_type,questions,required,graded,max_score,passing_score,max_attempts,target_type,sort_order) values('67402026-1002-4000-8000-000004000002','67402026-1002-4000-8000-000004000001','Knowledge check
---HE---
