insert into public.training_lesson_packs(course_id,revision,content) values('67402026-1002-4000-8000-000005000001','2026-10-02.v1','{"key": "transmission", "domain": "mechanical", "title": ["Shafts, bearings & transmission", "צירים, מיסבים ותמסורת"], "goal": ["Trace motion and inspect alignment, support and retention.", "עקבו אחר תנועה ובדקו יישור, תמיכה וקיבוע."], "sources": [["REV · FRC Robot Basics, bearings and chain examples", "https://www.revrobotics.com/content/docs/FRC-Robot-Basics-Guide.pdf"]], "steps": [["In a reference assembly, follow motor → transmission → shaft → driven part. Identify which parts rotate together.", "בהרכבת דוגמה עקבו ממנוע לתמסורת, ציר וחלק מונע. זהו אילו חלקים מסתובבים יחד."], ["Record bearing supports, shaft retention and sprocket/pulley alignment on a drawing. Do not infer hidden retainers from an external view.", "תעדו תמיכות מיסב, קיבוע ציר ויישור גלגלי שרשרת/רצועה בשרטוט. אין להסיק קיבוע נסתר ממבט חיצוני."], ["On an unpowered practice assembly, inspect free motion, unwanted axial movement and interference using the design specification.", "בהרכבת תרגול ללא מתח בדקו תנועה חופשית, תנועה צירית לא רצויה והפרעות לפי המפרט."], ["Record the before/after condition of one adjustment. Powered tests require guarding, supervision and a defined procedure.", "תעדו מצב לפני ואחרי כוונון אחד. בדיקות עם מתח דורשות מיגון, פיקוח ונוהל מוגדר."]], "mistakes": [["Tightening a transmission until it binds is not a substitute for the correct tension procedure.", "הידוק תמסורת עד שנתקעת אינו תחליף לנוהל מתיחה נכון."], ["A shaft looking straight in CAD does not establish real alignment under load.", "ציר שנראה ישר ב-CAD אינו מוכיח יישור בפועל תחת עומס."]], "practical": [["Map a transmission and its supports", "מיפוי תמסורת ותמיכות"], ["Inspect an unpowered assembly", "בדיקת הרכבה ללא מתח"]], "rubrics": [[["Input/output and rotating groups identified", "זוהו קלט/פלט וקבוצות מסתובבות"], ["Bearing and retention locations labeled", "סומנו מיסבים וקיבועים"], ["Ratio calculated from actual tooth counts", "יחס חושב ממספרי שיניים בפועל"], ["Unknown parts explicitly marked", "חלקים לא ידועים סומנו במפורש"]], [["Power isolated and stored energy handled by procedure", "מתח נותק ואנרגיה אגורה טופלה לפי נוהל"], ["Alignment and retention checked against drawing", "יישור וקיבוע נבדקו מול שרטוט"], ["Motion/interference observations recorded", "תועדו תצפיות תנועה/הפרעה"], ["Reviewer checks findings before powered test", "בודק בוחן ממצאים לפני בדיקה עם מתח"]]], "quizId": "67402026-1002-4000-8000-000005000002", "practicalIds": ["67402026-1002-4000-8000-000005000003", "67402026-1002-4000-8000-000005000004"], "sourceChecked": "2026-10-02", "sourcePolicy": "Linked living documentation; confirm the installed hardware and current instructions before practical work."}'::jsonb) on conflict(course_id) do nothing;
