insert into public.training_lesson_packs(course_id,revision,content) values('67402026-1002-4000-8000-000006000001','2026-10-02.v1','{"key": "mechanism-tests", "domain": "drive_pit", "title": ["Intake & shooter testing", "בדיקות איסוף וירי"], "goal": ["Measure repeated pickups and shots with a clear success definition.", "מדדו איסופים ויריות חוזרים עם הגדרת הצלחה ברורה."], "sources": [["WPILib · wiring best practices and baseline checks", "https://docs.wpilib.org/en/stable/docs/hardware/hardware-basics/wiring-best-practices.html"], ["REV · FRC Robot Basics, mechanism examples", "https://www.revrobotics.com/content/docs/FRC-Robot-Basics-Guide.pdf"]], "steps": [["Choose a supervised test area and a success criterion before running. Record robot configuration, battery, game pieces, distance and procedure.", "בחרו אזור בדיקה מפוקח וקריטריון הצלחה מראש. תעדו תצורה, סוללה, חלקי משחק, מרחק ונוהל."], ["For intake tests, count presented pieces, collected pieces and jams. Keep approach and piece placement repeatable.", "בבדיקות איסוף ספרו חלקים שהוצגו, נאספו ותקיעות. שמרו על גישה ומיקום חלקים חוזרים."], ["For shooting, record attempted and successful shots plus elapsed time. Accuracy and throughput answer different questions.", "בירי תעדו ניסיונות ופגיעות מוצלחות וזמן. דיוק וקצב עונים על שאלות שונות."], ["Save every trial, including failures. Change one factor, link the baseline and repair task, then retest with equivalent conditions.", "שמרו כל ניסיון, כולל כישלונות. שנו גורם אחד, קשרו בסיס ומשימת תיקון וחזרו על בדיקה בתנאים דומים."]], "mistakes": [["One successful shot is not a reliability estimate. Show the sample count and spread.", "ירייה מוצלחת אחת אינה אומדן אמינות. הציגו מספר ניסיונות ופיזור."], ["A simulated result is not measured robot performance.", "תוצאה מדומה אינה ביצוע שנמדד ברובוט."]], "practical": [["Record repeated intake trials", "תיעוד ניסיונות איסוף חוזרים"], ["Compare repeated shooting trials", "השוואת ניסיונות ירי חוזרים"]], "rubrics": [[["Supervisor, test area and pass definition agreed before testing", "סוכמו פיקוח, אזור וקריטריון מעבר לפני בדיקה"], ["Setup and procedure recorded", "תועדו תצורה ונוהל"], ["At least five trials include duration, counts and jams", "לפחות חמישה ניסיונות כוללים זמן, ספירות ותקיעות"], ["Shared test record linked as evidence", "רשומת בדיקה משותפת קושרה כראיה"]], [["Distance, target, game pieces and battery conditions recorded", "מרחק, מטרה, חלקי משחק ותנאי סוללה תועדו"], ["At least five baseline and five retest trials", "לפחות חמישה ניסיונות בסיס וחמישה חוזרים"], ["One change and any confounding conditions disclosed", "תועד שינוי אחד וכל תנאי מפריע"], ["Comparison reports counts, variability and limits without claiming causation", "השוואה מציגה ספירות, שונות ומגבלות בלי לטעון לסיבתיות"]]], "quizId": "67402026-1002-4000-8000-000006000002", "practicalIds": ["67402026-1002-4000-8000-000006000003", "67402026-1002-4000-8000-000006000004"], "sourceChecked": "2026-10-02", "sourcePolicy": "Linked living documentation; confirm the installed hardware and current instructions before practical work."}'::jsonb) on conflict(course_id) do nothing;
insert into public.training_assessments(id,course_id,title,instructions,assessment_type,questions,required,graded,max_score,passing_score,max_attempts,target_type,sort_order) values('67402026-1002-4000-8000-000006000002','67402026-1002-4000-8000-000006000001','Knowledge check
---HE---
בדיקת ידע','Answer all ten questions. Review the lesson after feedback; practical qualification also requires both demonstrations to be approved.
---HE---
ענו על עשר השאלות. חזרו לשיעור לאחר משוב; הסמכה מעשית דורשת גם אישור לשתי ההדגמות.','quiz','[{"id": "q1", "prompt": "Define success…\n---HE---\nמגדירים הצלחה…", "kind": "single_choice", "options": ["Before collecting results\n---HE---\nלפני איסוף תוצאות", "After seeing the best run\n---HE---\nאחרי הניסיון הטוב ביותר", "Only when publishing\n---HE---\nרק בפרסום"], "points": 1}, {"id": "q2", "prompt": "Record a jam…\n---HE---\nמתעדים תקיעה…", "kind": "single_choice", "options": ["By deleting the trial\n---HE---\nבמחיקת הניסיון", "Only if it happens ten times\n---HE---\nרק אם קרתה עשר פעמים", "As a fault, including the failed trial\n---HE---\nכתקלה, כולל הניסיון שנכשל"], "points": 1}, {"id": "q3", "prompt": "Accuracy is…\n---HE---\nדיוק הוא…", "kind": "single_choice", "options": ["Always equal to throughput\n---HE---\nתמיד שווה לקצב", "Successful shots divided by attempted shots\n---HE---\nפגיעות מוצלחות חלקי ניסיונות ירי", "Shots divided by battery voltage\n---HE---\nיריות חלקי מתח סוללה"], "points": 1}, {"id": "q4", "prompt": "Throughput uses…\n---HE---\nקצב משתמש ב…", "kind": "single_choice", "options": ["Successful pieces and elapsed time\n---HE---\nחלקים מוצלחים וזמן שחלף", "Only a photo\n---HE---\nרק בתצלום", "Only robot color\n---HE---\nרק בצבע רובוט"], "points": 1}, {"id": "q5", "prompt": "A fair comparison should…\n---HE---\nהשוואה הוגנת צריכה…", "kind": "single_choice", "options": ["Change every variable\n---HE---\nלשנות כל משתנה", "Omit failures\n---HE---\nלהשמיט כישלונות", "Keep procedure and conditions equivalent\n---HE---\nלשמור על נוהל ותנאים דומים"], "points": 1}, {"id": "q6", "prompt": "An unknown battery voltage is…\n---HE---\nמתח סוללה לא ידוע הוא…", "kind": "single_choice", "options": ["Written as zero\n---HE---\nנכתב כאפס", "Recorded as unknown\n---HE---\nנרשם כלא ידוע", "Assumed perfect\n---HE---\nמונח כמושלם"], "points": 1}, {"id": "q7", "prompt": "One successful trial establishes…\n---HE---\nניסיון מוצלח אחד קובע…", "kind": "single_choice", "options": ["That single observed outcome\n---HE---\nאת התוצאה הבודדת שנצפתה", "Guaranteed match reliability\n---HE---\nאמינות משחק מובטחת", "A championship result\n---HE---\nתוצאת אליפות"], "points": 1}, {"id": "q8", "prompt": "Simulation and physical trials should…\n---HE---\nניסיונות סימולציה ופיזיים צריכים…", "kind": "single_choice", "options": ["Be pooled as identical evidence\n---HE---\nלהתאחד כראיות זהות", "Have their labels removed\n---HE---\nלהיות ללא תוויות", "Remain clearly distinguished\n---HE---\nלהישאר מובחנים בבירור"], "points": 1}, {"id": "q9", "prompt": "A changed setup is saved…\n---HE---\nתצורה ששונתה נשמרת…", "kind": "single_choice", "options": ["Without a change note\n---HE---\nללא הערת שינוי", "As a new snapshot linked to baseline\n---HE---\nכתמונת מצב חדשה המקושרת לבסיס", "By overwriting the old run\n---HE---\nבדריסת ניסיון ישן"], "points": 1}, {"id": "q10", "prompt": "A repair is validated by…\n---HE---\nתיקון מאומת באמצעות…", "kind": "single_choice", "options": ["Equivalent retests and responsible review\n---HE---\nבדיקות חוזרות דומות ובדיקה אחראית", "Closing a task alone\n---HE---\nסגירת משימה בלבד", "Passing a quiz alone\n---HE---\nמעבר מבחן בלבד"], "points": 1}]'::jsonb,true,true,10,8,5,'all',10) on conflict(id) do nothing;
insert into public.training_assessment_answer_keys(assessment_id,answers) values('67402026-1002-4000-8000-000006000002','{"q1": ["Before collecting results\n---HE---\nלפני איסוף תוצאות"], "q2": ["As a fault, including the failed trial\n---HE---\nכתקלה, כולל הניסיון שנכשל"], "q3": ["Successful shots divided by attempted shots\n---HE---\nפגיעות מוצלחות חלקי ניסיונות ירי"], "q4": ["Successful pieces and elapsed time\n---HE---\nחלקים מוצלחים וזמן שחלף"], "q5": ["Keep procedure and conditions equivalent\n---HE---\nלשמור על נוהל ותנאים דומים"], "q6": ["Recorded as unknown\n---HE---\nנרשם כלא ידוע"], "q7": ["That single observed outcome\n---HE---\nאת התוצאה הבודדת שנצפתה"], "q8": ["Remain clearly distinguished\n---HE---\nלהישאר מובחנים בבירור"], "q9": ["As a new snapshot linked to baseline\n---HE---\nכתמונת מצב חדשה המקושרת לבסיס"], "q10": ["Equivalent retests and responsible review\n---HE---\nבדיקות חוזרות דומות ובדיקה אחראית"]}'::jsonb) on conflict(assessment_id) do nothing;
insert into public.training_assessments(id,course_id,title,instructions,assessment_type,questions,required,graded,max_attempts,target_type,sort_order) values('67402026-1002-4000-8000-000006000003','67402026-1002-4000-8000-000006000001','Record repeated intake trials
---HE---
תיעוד ניסיונות איסוף חוזרים','Record repeated intake trials
• Supervisor, test area and pass definition agreed before testing
• Setup and procedure recorded
• At least five trials include duration, counts and jams
• Shared test record linked as evidence
Submit observations and an evidence link. A responsible reviewer must verify every criterion; a self-check is not certification.
---HE---
תיעוד ניסיונות איסוף חוזרים
• סוכמו פיקוח, אזור וקריטריון מעבר לפני בדיקה
• תועדו תצורה ונוהל
• לפחות חמישה ניסיונות כוללים זמן, ספירות ותקיעות
• רשומת בדיקה משותפת קושרה כראיה
הגישו תצפיות וקישור לראיה. בודק אחראי חייב לאמת כל קריטריון; בדיקה עצמית אינה הסמכה.','practical','[]',true,false,10,'all',20) on conflict(id) do nothing;
insert into public.training_assessments(id,course_id,title,instructions,assessment_type,questions,required,graded,max_attempts,target_type,sort_order) values('67402026-1002-4000-8000-000006000004','67402026-1002-4000-8000-000006000001','Compare repeated shooting trials
---HE---
השוואת ניסיונות ירי חוזרים','Compare repeated shooting trials
• Distance, target, game pieces and battery conditions recorded
• At least five baseline and five retest trials
• One change and any confounding conditions disclosed
• Comparison reports counts, variability and limits without claiming causation
Submit observations and an evidence link. A responsible reviewer must verify every criterion; a self-check is not certification.
---HE---
השוואת ניסיונות ירי חוזרים
• מרחק, מטרה, חלקי משחק ותנאי סוללה תועדו
• לפחות חמישה ניסיונות בסיס וחמישה חוזרים
• תועד שינוי אחד וכל תנאי מפריע
• השוואה מציגה ספירות, שונות ומגבלות בלי לטעון לסיבתיות
הגישו תצפיות וקישור לראיה. בודק אחראי חייב לאמת כל קריטריון; בדיקה עצמית אינה הסמכה.','practical','[]',true,false,10,'all',30) on conflict(id) do nothing;
